-- Global asset library (wave 2): 016 PEOPLE + folder r-w + kit (tanaman, pintu,
-- bak mandi, meja, pagar/lampu jalan) — 70 model GLB terkurasi dari
-- ~2.160 SKP, dikonversi Blender & diupload ke storage
-- asset-library/global/furniture/. `is_public = true` membuat aset tampil di
-- My Library SEMUA user (read-only pemakaian; kepemilikan tetap owner).
-- Idempotent: on conflict do nothing; guard bila profile owner tak ada (dev DB).

alter table user_assets add column if not exists is_public boolean not null default false;
create index if not exists user_assets_public_idx on user_assets(is_public) where is_public;

insert into user_assets
  (id, user_id, name, category, source_type, source_name, original_filename,
   model_url, file_size_bytes, width_m, depth_m, height_m,
   license_confirmation, status, is_public)
